CREATE OR REPLACE FUNCTION public.whiteboard_create_render_job(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_render_id uuid;
  v_project_exists boolean;
  v_result jsonb;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM app.whiteboard_projects
    WHERE id = p_project_id AND student_id = auth.uid()
  ) INTO v_project_exists;

  IF NOT v_project_exists THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Project not found or unauthorized'
    );
  END IF;

  INSERT INTO app.whiteboard_renders (
    project_id,
    status,
    progress
  ) VALUES (
    p_project_id,
    'queued',
    0
  )
  RETURNING id INTO v_render_id;

  v_result := jsonb_build_object(
    'success', true,
    'render_id', v_render_id
  );

  RETURN v_result;
END;
$function$
